"""Real package metadata and host projections; generated bytes, no native audit."""

import json
import os
import shutil
import stat
from dataclasses import replace
from pathlib import Path
from zipfile import ZipFile

import pytest
from test_project_query import project as legacy_project

from sciplot_core.delivery.package_builder import _build_staged_delivery
from sciplot_core.delivery.package_validation import verify_delivery_package
from sciplot_core.foundation.file_hashing import file_sha256
from sciplot_core.launchers.delivery_binding import delivery_binding_from_content
from sciplot_core.launchers.delivery_inspection import inspect_delivery_launcher_contract
from sciplot_core.project_store import FileProjectStore, ResourceRoot
from sciplot_core.project_store.runtime import project_runtime, projected_runtime_directory, resolve_runtime_path
from sciplot_core.studio_core.project_query import inspect_project


def _project_and_delivery(tmp_path: Path, *, foreign_binding: str | None = None, snapshot: bool = False):
    project = legacy_project.__wrapped__(tmp_path)
    delivery = tmp_path / "visible"
    request_path = project / "plot_request.json"
    request = json.loads(request_path.read_bytes())
    request["delivery_output"] = str(delivery)
    request_path.write_text(json.dumps(request))
    registry_path = project / "studio/figure_set.json"
    registry = json.loads(registry_path.read_bytes())
    registry["figures"] = registry["figures"][:1]
    registry_path.write_text(json.dumps(registry))
    shutil.rmtree(project / "studio/figures")
    run = project / "runs/studio_001"
    run.mkdir(parents=True)
    shutil.copytree(project / "studio", run / "studio")
    (run / "request_snapshot.json").write_text(json.dumps(request))
    document = run / "studio/document.vsz"
    exports, pdfs, tiffs = [], [], []
    for fmt, suffix, reports in [("pdf", ".pdf", pdfs), ("tiff_300", "_300dpi.tiff", tiffs)]:
        path = run / ("document" + suffix)
        path.write_bytes(b"generated metadata-only artifact")
        item = {"path": str(path), "sha256": file_sha256(path)}
        exports.append({**item, "document": str(document), "format": fmt})
        reports.append(item)
    manifest_path = run / "manifest.json"
    manifest = {"request": request, "ready_to_use": True,
                "veusz_document_hashes": {str(document): file_sha256(document)},
                "qa": {"status": "passed", "pdfs": pdfs, "tiffs": tiffs},
                "result": {"exports": exports}}
    manifest.update(request_path=str(request_path), input=request["input"],
                    figures=[item["path"] for item in manifest["result"]["exports"]],
                    veusz_documents=list(manifest["veusz_document_hashes"]))
    manifest["result"]["processed_source"] = request["input"]
    manifest_path.write_text(json.dumps(manifest))
    record = _build_staged_delivery(run, manifest=manifest,
                                   delivery_dir=delivery, final_root=delivery)
    assert record["complete"] and record["verification"]["passed"], record["verification"]
    if foreign_binding is not None:
        launcher = delivery / "Open_in_Veusz.command"
        content = launcher.read_text()
        binding = delivery_binding_from_content(content)
        assert binding is not None
        if foreign_binding == "root":
            forged = replace(binding, root=str(tmp_path / "foreign-root"))
        else:
            foreign = tmp_path / "foreign-project"
            shutil.copytree(project, foreign)
            forged = replace(binding, request=str(foreign / "plot_request.json"))
        launcher.write_text(content.replace(binding.to_line(), forged.to_line()))
        record["open_in_veusz_sha256"] = file_sha256(launcher)
        record["launcher_contract"] = inspect_delivery_launcher_contract(delivery)
        assert verify_delivery_package(record, expected_root=delivery, expected_manifest=manifest)["passed"]
    manifest["delivery_package"] = record
    manifest_path.write_text(json.dumps(manifest))
    locations = {"delivery": delivery}
    if snapshot:
        archive = tmp_path / (project.name + ".zip")
        with ZipFile(archive, "w") as output:
            output.writestr("logical-project.txt", "generated snapshot capability")
        locations["snapshot"] = ResourceRoot(tmp_path, (archive.name,))
    store = FileProjectStore(project, locations=locations)
    store.snapshot(import_legacy=True)
    return project, delivery, store


def test_registered_current_delivery_observes_the_real_executable_package(tmp_path):
    project, delivery, _store = _project_and_delivery(tmp_path)
    launcher = delivery / "Open_in_Veusz.command"
    original = launcher.read_bytes(), launcher.stat().st_mode
    evidence = inspect_project(project)["delivery"]
    assert evidence["binding_current"] is True, evidence
    assert evidence["package_current"] is True, evidence
    assert evidence["path"] == str(delivery)
    assert (launcher.read_bytes(), launcher.stat().st_mode) == original


def test_explicit_import_reads_the_current_physical_delivery_with_original_identity(tmp_path):
    project, delivery, store = _project_and_delivery(tmp_path)
    original_request = store.read_bytes("plot_request.json")
    original_manifest = store.read_bytes("runs/studio_001/manifest.json")
    bundle = store.export_bundle(tmp_path / "bundle")
    project.rename(tmp_path / "offline-project")
    delivery.rename(tmp_path / "offline-delivery")
    moved = FileProjectStore.import_bundle(bundle, tmp_path / "moved")
    before = moved.snapshot()["generation"]
    evidence = inspect_project(moved.root)["delivery"]
    assert evidence["binding_current"] is True, evidence
    assert evidence["package_current"] is True, evidence
    assert evidence["path"] == str(moved.locations["delivery"])
    assert moved.read_bytes("plot_request.json") == original_request
    assert moved.read_bytes("runs/studio_001/manifest.json") == original_manifest
    assert moved.snapshot()["generation"] == before


def test_readonly_source_cache_cannot_supply_visible_launcher_evidence(tmp_path):
    _project, delivery, store = _project_and_delivery(tmp_path)
    with project_runtime(store):
        cache = resolve_runtime_path(delivery)
        assert cache != delivery
        cached_launcher, visible_launcher = cache / "Open_in_Veusz.command", delivery / "Open_in_Veusz.command"
        assert cached_launcher.read_bytes() == visible_launcher.read_bytes()
        assert stat.S_IMODE(cached_launcher.stat().st_mode) == 0o400
        assert stat.S_IMODE(visible_launcher.stat().st_mode) == 0o755
        assert projected_runtime_directory(delivery) == delivery
        with pytest.raises(ValueError):
            projected_runtime_directory(cache)


@pytest.mark.parametrize("mutation", ["launcher_mode", "launcher_hash", "native_hash", "extra", "missing", "alias"])
def test_current_delivery_refuses_mode_hash_membership_and_alias_drift(tmp_path, mutation):
    project, delivery, _store = _project_and_delivery(tmp_path)
    launcher = delivery / "Open_in_Veusz.command"
    if mutation == "launcher_mode":
        launcher.chmod(0o644)
    elif mutation == "launcher_hash":
        launcher.write_bytes(launcher.read_bytes() + b"\n# foreign\n")
    elif mutation == "native_hash":
        native = next((delivery / "project").glob("*.vsz"))
        native.write_bytes(native.read_bytes() + b"foreign")
    elif mutation == "extra":
        (delivery / "unregistered.txt").write_bytes(b"not declared")
    elif mutation == "missing":
        launcher.unlink()
    else:
        original = launcher.read_bytes()
        launcher.unlink()
        target = tmp_path / "foreign-launcher"
        target.write_bytes(original)
        target.chmod(0o755)
        launcher.symlink_to(target)
    evidence = inspect_project(project)["delivery"]
    assert evidence["current"] is False, evidence
    assert evidence["package_current"] is False, evidence


@pytest.mark.parametrize("foreign_binding", ["root", "project"])
def test_registered_complete_bytes_cannot_bind_a_foreign_delivery_owner(tmp_path, foreign_binding):
    project, delivery, _store = _project_and_delivery(tmp_path, foreign_binding=foreign_binding)
    assert inspect_delivery_launcher_contract(delivery)["ready"] is True
    evidence = inspect_project(project)["delivery"]
    assert evidence["binding_current"] is False, evidence
    assert evidence["current"] is False, evidence


def test_physical_directory_requires_the_original_host_root_and_a_whole_directory_cap(tmp_path):
    project, delivery, _store = _project_and_delivery(tmp_path)
    foreign = tmp_path / "same-bytes-foreign"
    shutil.copytree(delivery, foreign)
    with project_runtime(FileProjectStore(project, locations={"delivery": foreign})):
        with pytest.raises(ValueError, match="ownership identity"):
            projected_runtime_directory(delivery)
    with project_runtime(FileProjectStore(project, locations={"delivery": ResourceRoot(delivery, ("Open_in_Veusz.command",))})):
        with pytest.raises(ValueError, match="finite file grant"):
            projected_runtime_directory(delivery)
    with project_runtime(_store):
        with pytest.raises(ValueError, match="registered directory prefix"):
            projected_runtime_directory(foreign)


def test_whole_delivery_child_does_not_widen_a_finite_snapshot_parent(tmp_path, monkeypatch):
    from sciplot_core.project_store import directories

    _project, delivery, store = _project_and_delivery(tmp_path, snapshot=True)
    (tmp_path / "not-granted-private-file").write_bytes(b"outside the finite ZIP grant")
    parent = tmp_path.stat()
    names = directories._names

    def guarded(fd, **kwargs):
        info = os.fstat(fd)
        assert (info.st_dev, info.st_ino) != (parent.st_dev, parent.st_ino), "snapshot parent was enumerated"
        return names(fd, **kwargs)

    monkeypatch.setattr(directories, "_names", guarded)
    with project_runtime(store):
        assert projected_runtime_directory(delivery) == delivery
        with pytest.raises(ValueError, match="finite file grant"):
            projected_runtime_directory(tmp_path)


def test_project_inspection_never_materializes_delivery_as_a_source(tmp_path, monkeypatch):
    from sciplot_core.project_store import directories

    project, _delivery, _store = _project_and_delivery(tmp_path)
    before = {str(path): (file_sha256(path), path.stat().st_mode, path.stat().st_mtime_ns)
              for path in tmp_path.rglob("*") if path.is_file()}

    def reject_source_view(*args, **kwargs):
        pytest.fail("Read-only inspection must not materialize delivery source views")

    monkeypatch.setattr(directories, "resolve", reject_source_view)
    evidence = inspect_project(project)
    assert evidence["delivery"]["binding_current"] is True
    assert evidence["delivery"]["package_current"] is True
    assert evidence["qa"]["current"] is True
    assert {str(path): (file_sha256(path), path.stat().st_mode, path.stat().st_mtime_ns)
            for path in tmp_path.rglob("*") if path.is_file()} == before


def test_recorded_artifact_cannot_use_a_source_cache_as_current_physical_evidence(tmp_path):
    from sciplot_core.delivery.runtime_evidence import recorded_path_exists

    _project, delivery, store = _project_and_delivery(tmp_path)
    with project_runtime(store):
        cache = resolve_runtime_path(delivery)
        assert cache.is_dir()
        with pytest.raises(ValueError, match="source cache"):
            recorded_path_exists(cache)


def test_missing_physical_artifact_is_not_proved_by_its_surviving_source_cache(tmp_path):
    from sciplot_core.delivery.runtime_evidence import recorded_path_exists

    _project, delivery, store = _project_and_delivery(tmp_path)
    with project_runtime(store):
        cache = resolve_runtime_path(delivery)
        launcher = delivery / "Open_in_Veusz.command"
        launcher.unlink()
        assert (cache / launcher.name).is_file()
        with pytest.raises(ValueError):
            recorded_path_exists(delivery)


def test_recorded_artifact_keeps_exact_file_and_private_stage_io(tmp_path):
    from sciplot_core.delivery.runtime_evidence import recorded_path_exists

    _project, delivery, store = _project_and_delivery(tmp_path)
    private = tmp_path / "host-private-stage"
    private.mkdir()
    metadata = private / "manifest.json"
    metadata.write_text('{"private":true}')
    with project_runtime(store):
        assert recorded_path_exists(delivery / "Open_in_Veusz.command")
        assert recorded_path_exists(private) and recorded_path_exists(metadata)
        assert not recorded_path_exists(private / "missing.json")


def test_physical_artifact_reader_preserves_the_explicit_private_candidate(tmp_path):
    from test_project_candidate_runtime import fixture_candidate
    from sciplot_core.project_store.runtime import project_candidate_runtime, projected_runtime_artifact

    store, before, private = fixture_candidate(tmp_path)
    candidate = private / "studio/document.vsz"
    with project_candidate_runtime(store, private):
        candidate.write_bytes(b"explicit private native candidate")
        assert projected_runtime_artifact(store.root / "studio/document.vsz") == candidate
        assert projected_runtime_artifact(store.root / "studio/document.vsz").read_bytes() == candidate.read_bytes()
    assert (store.root / "studio/document.vsz").read_bytes() == b"native original"
    assert store.snapshot()["generation"] == before["generation"]
